C++<pre><code>vector&lt;vector&lt;int&gt;&gt; levelOrder(TreeNode* root) {
    vector&lt;vector&lt;int&gt;&gt; res;
    if (!root) return res;

    queue&lt;TreeNode*&gt; q;
    q.push(root);

    while (!q.empty()) {
        int sz = q.size();
        vector&lt;int&gt; level;
        while (sz--) {
            TreeNode* u = q.front();
            q.pop();
            level.push_back(u-&gt;val);
            if (u-&gt;left) q.push(u-&gt;left);
            if (u-&gt;right) q.push(u-&gt;right);
        }
        res.push_back(level);
    }
    return res;
}
