C++<pre><code>bool isBalanced(TreeNode* root) {
    function&lt;int(TreeNode*)&gt; h = [&amp;](TreeNode* u) {
        if (!u) return 0;
        int L = h(u-&gt;left);
        if (L == -1) return -1;
        int R = h(u-&gt;right);
        if (R == -1) return -1;
        if (abs(L - R) &gt; 1) return -1;
        return max(L, R) + 1;
    };
    return h(root) != -1;
}
