C++<pre><code>bool isMirror(TreeNode* a, TreeNode* b) {
    if (!a &amp;&amp; !b) return true;
    if (!a || !b) return false;
    if (a-&gt;val != b-&gt;val) return false;
    return isMirror(a-&gt;left, b-&gt;right) &amp;&amp; isMirror(a-&gt;right, b-&gt;left);
}

bool isSymmetric(TreeNode* root) {
    return !root || isMirror(root-&gt;left, root-&gt;right);
}
