C++<pre><code>vector&lt;int&gt; nextGreaterRight(vector&lt;int&gt;&amp; a) {
    int n = a.size();
    vector&lt;int&gt; nxt(n, -1);
    stack&lt;int&gt; st; // 下标，保持栈内值单调递减

    for (int i = n - 1; i &gt;= 0; i--) {
        while (!st.empty() &amp;&amp; a[st.top()] &lt;= a[i]) st.pop();
        if (!st.empty()) nxt[i] = st.top();
        st.push(i);
    }
    return nxt;
}
</code></pre>

C++<pre><code>bool validPopSeq(vector&lt;int&gt;&amp; in, vector&lt;int&gt;&amp; out) {
    stack&lt;int&gt; st;
    int j = 0;
    for (int x : in) {
        st.push(x);
        while (!st.empty() &amp;&amp; j &lt; (int)out.size() &amp;&amp; st.top() == out[j]) {
            st.pop();
            j++;
        }
    }
    return j == (int)out.size();
}
