C++<pre><code>int priority(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

bool isOp(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

string infixToPostfix(const string&amp; s) {
    string out;
    stack&lt;char&gt; ops;

    for (char c : s) {
        if (isdigit(c)) {
            out += c;
        } else if (c == '(') {
            ops.push(c);
        } else if (c == ')') {
            while (!ops.empty() &amp;&amp; ops.top() != '(') {
                out += ops.top();
                ops.pop();
            }
            if (!ops.empty()) ops.pop();
        } else if (isOp(c)) {
            while (!ops.empty() &amp;&amp; priority(ops.top()) &gt;= priority(c)) {
                out += ops.top();
                ops.pop();
            }
            ops.push(c);
        }
    }

    while (!ops.empty()) {
        out += ops.top();
        ops.pop();
    }
    return out;
}
</code></pre>

