C++<pre><code>ListNode* kthFromEnd(ListNode* head, int k) {
    ListNode *fast = head, *slow = head;
    while (k-- &amp;&amp; fast) fast = fast-&gt;next;
    if (k &gt;= 0) return nullptr;
    while (fast) {
        fast = fast-&gt;next;
        slow = slow-&gt;next;
    }
    return slow;
}
