C++<pre><code>ListNode* mergeTwo(ListNode* a, ListNode* b) {
    ListNode dummy;
    ListNode* tail = &amp;dummy;
    while (a &amp;&amp; b) {
        if (a-&gt;val &lt;= b-&gt;val) {
            tail-&gt;next = a;
            a = a-&gt;next;
        } else {
            tail-&gt;next = b;
            b = b-&gt;next;
        }
        tail = tail-&gt;next;
    }
    tail-&gt;next = a ? a : b;
    return dummy.next;
}
