C++<pre><code>int longestWindow(string s, int k) {
    vector&lt;int&gt; cnt(26, 0);
    int l = 0, ans = 0, maxFreq = 0;

    for (int r = 0; r &lt; (int)s.size(); r++) {
        maxFreq = max(maxFreq, ++cnt[s[r] - 'A']);
        while (r - l + 1 - maxFreq &gt; k) {
            cnt[s[l] - 'A']--;
            l++;
        }
        ans = max(ans, r - l + 1);
    }
    return ans;
}
</code></pre>

C++<pre><code>long long trap(vector&lt;int&gt;&amp; h) {
    int l = 0, r = (int)h.size() - 1;
    int lmax = 0, rmax = 0;
    long long ans = 0;

    while (l &lt;= r) {
        if (lmax &lt;= rmax) {
            lmax = max(lmax, h[l]);
            ans += max(0, lmax - h[l]);
            l++;
        } else {
            rmax = max(rmax, h[r]);
            ans += max(0, rmax - h[r]);
            r--;
        }
    }
    return ans;
}
</code></pre>

