C++<pre><code>#include &lt;bits/stdc++.h&gt;
using namespace std;

const int MAXV = 1005;

struct ArcNode {
    int adjvex;
    int weight;
    ArcNode* next;
};

struct VNode {
    int data;
    ArcNode* first;
};

struct ALGraph {
    VNode vertices[MAXV];
    int vexnum, arcnum;
    bool directed;
};

void initGraph(ALGraph&amp; G, int n, bool directed = false) {
    G.vexnum = n;
    G.arcnum = 0;
    G.directed = directed;
    for (int i = 1; i &lt;= n; i++) {
        G.vertices[i].data = i;
        G.vertices[i].first = nullptr;
    }
}

void addArc(ALGraph&amp; G, int u, int v, int w = 1) {
    ArcNode* p = new ArcNode{v, w, G.vertices[u].first};
    G.vertices[u].first = p;
}

void addEdge(ALGraph&amp; G, int u, int v, int w = 1) {
    addArc(G, u, v, w);
    if (!G.directed) addArc(G, v, u, w);
    G.arcnum++;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin &gt;&gt; n &gt;&gt; m;
    ALGraph G;
    initGraph(G, n, false);

    for (int i = 0; i &lt; m; i++) {
        int u, v;
        cin &gt;&gt; u &gt;&gt; v;
        addEdge(G, u, v);
    }

    vector&lt;int&gt; dist(n + 1, -1);
    queue&lt;int&gt; q;
    int s = 1;
    dist[s] = 0;
    q.push(s);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (ArcNode* p = G.vertices[u].first; p != nullptr; p = p-&gt;next) {
            int v = p-&gt;adjvex;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }

    return 0;
}
